const uint32_t *font_glyph(uint32_t cp)
{
    int lo = 0, hi = FONT_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        uint32_t v = g_font_table[mid].cp;
        if (v == cp) return g_font_bitmap[g_font_table[mid].idx];
        if (v < cp) lo = mid + 1; else hi = mid - 1;
    }
    return NULL;
}

int font_width(uint32_t cp)
{
    return font_glyph(cp) ? FONT_PX : 0;
}

int font_advance(uint32_t cp)
{
    int lo = 0, hi = FONT_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        uint32_t v = g_font_table[mid].cp;
        if (v == cp) return g_font_table[mid].adv;
        if (v < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
